-- Source: NAHB Builder Cost survey 2024 + Construction Financial Management Association data.
-- Safe to re-run. Grade A/B cells are NOT overwritten.

-- 1. regional_cells (non-US sub-national rows)
UPDATE regional_cells
SET cost_stack = jsonb_build_object(
  'rent_occupancy',         ROUND(rev_p50 * 0.02),
  'payroll_total',          ROUND(rev_p50 * 0.25),
  'cost_of_goods_sold',     ROUND(rev_p50 * 0.5),
  'utilities',              ROUND(rev_p50 * 0.01),
  'marketing_acquisition',  ROUND(rev_p50 * 0.02),
  'insurance_professional', ROUND(rev_p50 * 0.06),
  'equipment_maintenance',  ROUND(rev_p50 * 0.04),
  'regulatory_licensing',   ROUND(rev_p50 * 0.03),
  'refreshed_at',           '2026-05-24',
  'source_note',            'NAHB Builder Cost survey 2024 + Construction Financial Management Association data. Country revenue captures local price level implicitly.',
  'grade',                  'C'
)
WHERE industry_id = 'residential_construction'
  AND rev_p50 IS NOT NULL
  AND rev_p50 > 0
  AND (cost_stack IS NULL OR cost_stack->>'grade' IN ('C', 'D'));

