-- 3. extrapolated_cells (country-level fallback)
UPDATE extrapolated_cells
SET cost_stack = jsonb_build_object(
  'rent_occupancy',         ROUND(predicted_rev_per_firm * 0.02),
  'payroll_total',          ROUND(predicted_rev_per_firm * 0.25),
  'cost_of_goods_sold',     ROUND(predicted_rev_per_firm * 0.5),
  'utilities',              ROUND(predicted_rev_per_firm * 0.01),
  'marketing_acquisition',  ROUND(predicted_rev_per_firm * 0.02),
  'insurance_professional', ROUND(predicted_rev_per_firm * 0.06),
  'equipment_maintenance',  ROUND(predicted_rev_per_firm * 0.04),
  'regulatory_licensing',   ROUND(predicted_rev_per_firm * 0.03),
  'refreshed_at',           '2026-05-24',
  'source_note',            'NAHB Builder Cost survey 2024 + Construction Financial Management Association data. Country-level extrapolation; coarser than regional_cells.',
  'grade',                  'D'
)
WHERE industry_id = 'residential_construction'
  AND predicted_rev_per_firm IS NOT NULL
  AND predicted_rev_per_firm > 0
  AND (cost_stack IS NULL OR cost_stack->>'grade' IN ('C', 'D'));
